-- Hand-written: full-audit fix (FX-5, owner decision 2026-10-30): an invoice-family document the client has opened in the portal is never voided, generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `documents_viewed_no_void` BEFORE UPDATE OF status ON `documents` WHEN NEW.status = 'void' AND OLD.status <> 'void' AND OLD.viewed_at IS NOT NULL AND OLD.type IN ('proforma', 'tax_invoice', 'export_invoice') BEGIN SELECT RAISE(ABORT, 'documents_viewed_no_void: a document the client has opened in the portal is never voided; a credit note corrects it'); END;
